"use client";

import * as React from "react";
import Link from "next/link";
import { useSearchParams } from "next/navigation";
import { ArrowLeft, ArrowRight, Check, ChevronDown, CircleAlert, FileSpreadsheet, FileText, Info, Loader2, Search, ShieldCheck, UploadCloud, X } from "lucide-react";
import { Alert, AlertDescription, AlertTitle, Button, FileInput, Input, Select, cn } from "@fintrace/ui";
import { analyzeSourceFile, ApiClientError, confirmSourceMappings, createFinancialInvestigation, decideRelationship, editSourceMapping, fetchFinancialInvestigation, fetchFinancialInvestigations, fetchLatestReconciliation, fetchLifecycle, fetchReconciliationInvestigation, fetchReconciliationResults, fetchRelationships, fetchSourceAnalysis, fetchSourceFiles, fetchSourceMappings, investigateReconciliationResult, normalizeDataset, requestFinancialResolution, runInvestigationReconciliation, uploadSourceFile } from "../lib/api-client";
import type { ApiFinancialInvestigation, ApiInvestigation, ApiLifecycleResponse, ApiReconciliationResult, ApiReconciliationRun, ApiRelationshipProposal, ApiSourceAnalysis, ApiSourceFile, ApiSourceMapping, ResolutionActionCode } from "../lib/types";

const extensions = [".csv", ".xlsx"];
function requestKey() { return typeof crypto !== "undefined" && "randomUUID" in crypto ? crypto.randomUUID() : `${Date.now()}-${Math.random().toString(16).slice(2)}`; }
function money(minor: number, currency = "INR") { return new Intl.NumberFormat("en-IN", { style: "currency", currency, maximumFractionDigits: 0 }).format(minor / 100); }
function date(value: string | null) { return value ? new Intl.DateTimeFormat("en-IN", { day: "numeric", month: "short", year: "numeric" }).format(new Date(value)) : "Not set"; }
function label(value: string | null | undefined) { return (value ?? "").replaceAll("_", " ").toLowerCase().replace(/(^| )\w/g, character => character.toUpperCase()); }
function errorText(error: unknown) { return error instanceof ApiClientError ? error.message : "The request could not be completed. Check that the API is running and try again."; }
function isCanonicalClose(item: ApiFinancialInvestigation) { return item.name.toLowerCase().startsWith("august 2026 independent close") && item.status === "RECONCILED" && item.source_file_count >= 7; }
function canonicalClose(items: ApiFinancialInvestigation[]) { return items.find(isCanonicalClose) ?? items.find(item => item.name.toLowerCase().startsWith("august 2026 independent close")); }
function ambiguous(result: ApiReconciliationResult) { return result.status === "AMBIGUOUS" || `${result.exception_type ?? ""} ${result.findings.map(item => item.code).join(" ")}`.includes("AMBIGUOUS"); }
function needsEvidence(result: ApiReconciliationResult) { return ambiguous(result) || `${result.exception_type ?? ""} ${result.findings.map(item => item.code).join(" ")}`.match(/MISSING_REFERENCE|EVIDENCE_REQUIRED/); }
function inAttention(result: ApiReconciliationResult) { return ["NEEDS EVIDENCE", "NEEDS DECISION", "APPROVAL REQUIRED"].includes(state(result)); }
function state(result: ApiReconciliationResult) { const text = `${result.status} ${result.exception_type ?? ""} ${result.findings.map(item => item.code).join(" ")}`; if (result.status === "RECONCILED") return "RECONCILED"; if (result.status === "RECONCILED_WITH_VARIANCE") return "EXPECTED VARIANCE"; if (text.includes("APPROVAL_REQUIRED")) return "APPROVAL REQUIRED"; if (text.includes("NEEDS_DECISION")) return "NEEDS DECISION"; return needsEvidence(result) ? "NEEDS EVIDENCE" : "EXPLAINED"; }
function tone(value: string) { return value === "RECONCILED" ? "text-success bg-success/10" : value === "EXPECTED VARIANCE" ? "text-warning bg-warning/10" : value === "NEEDS DECISION" ? "text-destructive bg-destructive/10" : value === "NEEDS EVIDENCE" ? "text-warning bg-warning/10" : "text-info bg-info/10"; }

function CloseNav({ id }: { id: string }) { const params = useSearchParams(); const items = [{ label: "Overview", href: `/investigations/${id}` }, { label: "Data", href: `/investigations/${id}/data` }, { label: "Results", href: `/investigations/${id}/reconciliation` }, { label: "Attention", href: `/investigations/${id}/attention` }]; return <div className="mb-8 flex flex-wrap items-center gap-1 border-b border-border pb-1"><Link href="/investigations" className="mr-4 flex items-center gap-1.5 px-2 py-2 text-xs font-medium text-muted-foreground hover:text-foreground"><ArrowLeft className="h-3.5 w-3.5" />Closes</Link>{items.map(item => <Link key={item.label} href={item.href} className={cn("rounded-t-md px-3 py-2 text-xs font-semibold", (item.label === "Results" && params.get("result")) ? "text-primary" : "text-muted-foreground hover:text-foreground")}>{item.label}</Link>)}</div>; }
function Heading({ eyebrow, title, description, children }: { eyebrow: string; title: string; description?: string; children?: React.ReactNode }) { return <div className="mb-8 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><div className="mb-2 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground">{eyebrow}</div><h1 className="text-[30px] font-bold tracking-[-0.04em] text-foreground">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm leading-6 text-muted-foreground">{description}</p>}</div>{children && <div className="flex shrink-0 items-center gap-2">{children}</div>}</div>; }
function Metric({ name, value, color }: { name: string; value: string; color: string }) { return <div><div className="text-[10px] font-bold uppercase tracking-[0.12em] text-muted-foreground">{name}</div><div className={cn("mt-2 text-2xl font-bold", color)}>{value}</div></div>; }

export function CloseHomePage() {
  const [items, setItems] = React.useState<ApiFinancialInvestigation[]>([]); const [loading, setLoading] = React.useState(true); const [error, setError] = React.useState<string | null>(null);
  React.useEffect(() => { fetchFinancialInvestigations().then(setItems).catch(e => setError(errorText(e))).finally(() => setLoading(false)); }, []);
  if (loading) return <div role="status" className="text-sm text-muted-foreground">Loading current close…</div>;
  if (error) return <Alert variant="destructive"><AlertTitle>Unable to load FinTrace</AlertTitle><AlertDescription>{error}</AlertDescription></Alert>;
  const selectedId = typeof window !== "undefined" ? new URLSearchParams(window.location.search).get("investigation") : null; const selected = items.find(item => item.id === selectedId) ?? canonicalClose(items);
  if (selected) return <HomeSummary investigation={selected} />;
  return <div className="mx-auto max-w-5xl"><Heading eyebrow="FinTrace" title="Financial Close Control" description="Upload a period, let FinTrace handle the technical work, and review only what needs your attention." /><div className="max-w-2xl rounded-2xl border border-border bg-card p-8"><div className="text-sm font-semibold text-foreground">No canonical August close</div><p className="mt-2 text-sm leading-6 text-muted-foreground">Prepare the validated August close in this workspace before recording the controller walkthrough.</p><div className="mt-6"><Button asChild><Link href="/investigations/new">Start a new close</Link></Button></div></div></div>;
}

function HomeSummary({ investigation }: { investigation: ApiFinancialInvestigation }) { const [run, setRun] = React.useState<ApiReconciliationRun | null>(null); const [results, setResults] = React.useState<ApiReconciliationResult[]>([]); React.useEffect(() => { fetchLatestReconciliation(investigation.id).then(r => { setRun(r); return fetchReconciliationResults(investigation.id, r.id); }).then(setResults).catch(() => undefined); }, [investigation.id]); const needsEvidenceCount = run?.ambiguous_count ?? results.filter(ambiguous).length; const attention = results.filter(inAttention); const variance = results.filter(item => item.status === "RECONCILED_WITH_VARIANCE").length; const reconciled = run ? Math.max(0, run.reconciled_count - variance) : results.filter(item => item.status === "RECONCILED").length; const explained = run?.exception_count ?? results.filter(item => !inAttention(item) && item.status !== "RECONCILED" && item.status !== "RECONCILED_WITH_VARIANCE").length; return <div className="mx-auto max-w-5xl"><Heading eyebrow="FinTrace" title="Financial Close Control" description="A simple view of what reconciled, what FinTrace explained, and what still needs evidence or approval." /><section className="max-w-3xl"><div className="text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground">Current close</div><h2 className="mt-2 text-3xl font-bold tracking-[-0.035em] text-foreground">{investigation.name}</h2><p className="mt-2 text-sm text-muted-foreground">{date(investigation.period_start)} – {date(investigation.period_end)} <span className="mx-2 text-border">·</span> {investigation.source_file_count || 7} source systems</p><div className="mt-7 flex flex-wrap items-center gap-3"><span className="rounded-full bg-warning/10 px-3 py-1.5 text-xs font-bold text-warning">{attention.length ? "Needs attention" : "Ready to sign off"}</span><span className="text-sm font-semibold text-foreground">{run ? `${run.records_consumed.toLocaleString()} / ${run.records_expected.toLocaleString()} records accounted for` : "Data not run yet"}</span></div><div className="mt-9 grid grid-cols-2 gap-y-6 border-y border-border py-6 sm:grid-cols-4"><Metric name="Reconciled" value={String(reconciled)} color="text-success" /><Metric name="Expected variance" value={String(variance)} color="text-warning" /><Metric name="Explained" value={String(explained)} color="text-info" /><Metric name="Needs evidence" value={String(needsEvidenceCount)} color="text-destructive" /></div><div className="mt-7 flex flex-wrap items-end justify-between gap-5 border-b border-border pb-7"><div><div className="text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground">Potential exposure</div><div className="mt-2 text-3xl font-bold tracking-[-0.04em] text-foreground">{run ? money(run.open_exposure_minor, investigation.base_currency) : "—"}</div></div><div className="flex gap-2"><Button asChild><Link href={attention.length ? `/investigations/${investigation.id}/attention` : `/investigations/${investigation.id}/reconciliation`}>{attention.length ? `Review ${attention.length} attention item${attention.length === 1 ? "" : "s"}` : "View close"}<ArrowRight className="h-3.5 w-3.5" /></Link></Button><Button asChild variant="ghost"><Link href={`/investigations/${investigation.id}/reconciliation`}>View close</Link></Button></div></div></section></div>; }

export function CloseInvestigationsPage() { const [items, setItems] = React.useState<ApiFinancialInvestigation[]>([]); const [query, setQuery] = React.useState(""); const [error, setError] = React.useState<string | null>(null); const [launching, setLaunching] = React.useState(false); React.useEffect(() => { fetchFinancialInvestigations().then(setItems).catch(e => setError(errorText(e))); }, []); async function launch() { setLaunching(true); const close = canonicalClose(items); if (close) { window.location.href = `/?investigation=${encodeURIComponent(close.id)}`; return; } setError("The canonical August close is not prepared in this workspace yet."); setLaunching(false); } const filtered = items.filter(item => `${item.name} ${item.status} ${item.base_currency}`.toLowerCase().includes(query.toLowerCase())).sort((a, b) => Number(isCanonicalClose(b)) - Number(isCanonicalClose(a))); return <div className="mx-auto max-w-5xl"><Heading eyebrow="Closes" title="Financial closes" description="The prepared August 2026 close is the validated demo period. Open it to review the results, or start a new close with your own exports."><Button asChild><Link href="/investigations/new">Start a new close</Link></Button><Button onClick={() => void launch()} disabled={launching} variant="subtle">{launching ? "Opening…" : "Open prepared August 2026 close"}</Button></Heading>{error && <Alert variant="destructive" className="mb-5"><AlertDescription>{error}</AlertDescription></Alert>}<div className="mb-5 max-w-xl"><div className="relative"><Search className="pointer-events-none absolute left-3 top-3 h-4 w-4 text-muted-foreground" /><Input aria-label="Search closes" className="pl-9" placeholder="Search closes" value={query} onChange={e => setQuery(e.target.value)} /></div></div><div className="divide-y divide-border border-y border-border">{filtered.map(item => <Link key={item.id} href={`/investigations/${item.id}`} className="flex items-center justify-between gap-4 py-5 transition-colors hover:bg-muted/30"><div><div className="flex items-center gap-3"><h2 className="text-sm font-bold text-foreground">{item.name}</h2>{isCanonicalClose(item) && <span className="text-[10px] font-bold uppercase tracking-wide text-primary">Canonical demo</span>}</div><p className="mt-1 text-xs text-muted-foreground">{date(item.period_start)} – {date(item.period_end)} <span className="mx-1">·</span> {item.source_file_count} files <span className="mx-1">·</span> {item.base_currency}</p></div><ArrowRight className="h-4 w-4 text-muted-foreground" /></Link>)}</div>{!filtered.length && <div className="py-12 text-sm text-muted-foreground">No closes match your search.</div>}</div>; }

export function CloseNewPage() { const [form, setForm] = React.useState({ name: "", period_start: "", period_end: "", base_currency: "INR" }); const [saving, setSaving] = React.useState(false); const [error, setError] = React.useState<string | null>(null); async function submit(e: React.FormEvent<HTMLFormElement>) { e.preventDefault(); setSaving(true); try { const submittedForm = { ...form, name: e.currentTarget.querySelector<HTMLInputElement>("#close-name")?.value || form.name, period_start: e.currentTarget.querySelector<HTMLInputElement>("#close-start")?.value || form.period_start, period_end: e.currentTarget.querySelector<HTMLInputElement>("#close-end")?.value || form.period_end, base_currency: e.currentTarget.querySelector<HTMLSelectElement>("#close-currency")?.value || form.base_currency }; const result = await createFinancialInvestigation(submittedForm, requestKey()); window.location.href = `/investigations/${result.id}/data`; } catch (err) { setError(errorText(err)); setSaving(false); } } return <div className="mx-auto max-w-3xl"><Heading eyebrow="Start close" title="Start a financial close" description="Name the period, set its dates, then upload the exports used during the month." />{error && <Alert variant="destructive" className="mb-5"><AlertDescription>{error}</AlertDescription></Alert>}<div className="rounded-2xl border border-border bg-card p-7"><form onSubmit={submit} className="space-y-6"><div><label htmlFor="close-name" className="text-xs font-semibold text-foreground">Close name</label><Input id="close-name" required className="mt-2 h-11" placeholder="August 2026 Close" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} /></div><div className="grid gap-5 sm:grid-cols-3"><div><label htmlFor="close-start" className="text-xs font-semibold text-foreground">Period start</label><Input id="close-start" type="date" required className="mt-2 h-11" value={form.period_start} onChange={e => setForm({ ...form, period_start: e.target.value })} /></div><div><label htmlFor="close-end" className="text-xs font-semibold text-foreground">Period end</label><Input id="close-end" type="date" required className="mt-2 h-11" value={form.period_end} onChange={e => setForm({ ...form, period_end: e.target.value })} /></div><div><label htmlFor="close-currency" className="text-xs font-semibold text-foreground">Currency</label><Select id="close-currency" className="mt-2 h-11" value={form.base_currency} onChange={e => setForm({ ...form, base_currency: e.target.value })}><option value="INR">INR · Indian Rupee</option><option value="USD">USD · US Dollar</option><option value="EUR">EUR · Euro</option></Select></div></div><div className="flex justify-end border-t border-border pt-6"><Button type="submit" disabled={saving}>{saving ? "Creating close…" : "Create close"}</Button></div></form></div></div>; }

export function CloseDataPage({ investigationId }: { investigationId: string }) { const [investigation, setInvestigation] = React.useState<ApiFinancialInvestigation | null>(null); const [sources, setSources] = React.useState<ApiSourceFile[]>([]); const [relationships, setRelationships] = React.useState<ApiRelationshipProposal[]>([]); const [error, setError] = React.useState<string | null>(null); const [uploading, setUploading] = React.useState(false); const [running, setRunning] = React.useState(false); const [reviewSource, setReviewSource] = React.useState<ApiSourceFile | null>(null); const refresh = React.useCallback(async () => { const [loaded, files, links] = await Promise.all([fetchFinancialInvestigation(investigationId), fetchSourceFiles(investigationId), fetchRelationships(investigationId).catch(() => [])]); setInvestigation(loaded); setSources(files); setRelationships(links); }, [investigationId]); React.useEffect(() => { void refresh().catch(e => setError(errorText(e))); }, [refresh]); async function upload(e: React.ChangeEvent<HTMLInputElement>) { const files = Array.from(e.target.files ?? []); e.target.value = ""; if (!files.length) return; const invalid = files.find(file => !extensions.some(ext => file.name.toLowerCase().endsWith(ext))); if (invalid) { setError(`${invalid.name} is not supported. Upload CSV or XLSX files only.`); return; } setUploading(true); setError(null); try { for (const file of files) { const source = await uploadSourceFile(investigationId, file, requestKey()); const analysis = await analyzeSourceFile(investigationId, source.id); const mappings = await fetchSourceMappings(investigationId, source.id); if (analysis.classification_confidence >= .9 && mappings.every(item => !item.required || Boolean(item.canonical_field && !item.ignored))) await confirmSourceMappings(investigationId, source.id); } await refresh(); } catch (err) { setError(errorText(err)); } finally { setUploading(false); } } async function runClose() { setRunning(true); setError(null); try { const safe = relationships.filter(item => item.status === "PROPOSED" && item.confidence >= .9 && item.value_overlap_percent >= 99 && item.duplicate_key_rate_percent === 0 && (item.amount_agreement_percent === null || item.amount_agreement_percent >= 95) && (item.temporal_consistency_percent === null || item.temporal_consistency_percent >= 95)); await Promise.all(safe.map(item => decideRelationship(investigationId, item.id, "ACCEPTED"))); const dataset = await normalizeDataset(investigationId); const run = await runInvestigationReconciliation(investigationId, dataset.id); window.location.href = `/investigations/${investigationId}/reconciliation?run=${encodeURIComponent(run.id)}`; } catch (err) { setError(errorText(err)); setRunning(false); } } if (!investigation) return error ? <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert> : <div role="status" className="text-sm text-muted-foreground">Loading close data…</div>; const reviewCount = sources.filter(s => s.status !== "READY").length; const uncertain = relationships.filter(item => item.status === "PROPOSED" && (item.confidence < .9 || item.duplicate_key_rate_percent > .0 || item.value_overlap_percent < 99)); return <div className="mx-auto max-w-5xl"><CloseNav id={investigationId} /><Heading eyebrow="Data" title={investigation.name} description="Upload exports from the systems used during this period."><Button onClick={() => void runClose()} disabled={running || !sources.length}>{running ? <><Loader2 className="h-3.5 w-3.5 animate-spin" />Running close…</> : "Run close"}</Button></Heading>{error && <Alert variant="destructive" className="mb-5"><AlertDescription>{error}</AlertDescription></Alert>}<div className="rounded-2xl border border-dashed border-primary/35 bg-primary/[0.025] px-6 py-10 text-center"><UploadCloud className="mx-auto h-8 w-8 text-primary" /><h2 className="mt-4 text-base font-bold text-foreground">Add close exports</h2><p className="mx-auto mt-2 max-w-md text-sm leading-6 text-muted-foreground">Choose CSV or XLSX files together. FinTrace identifies the source and understands the routine setup automatically.</p><label className="mt-6 inline-flex cursor-pointer items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-xs font-bold text-primary-foreground">{uploading ? "Understanding files…" : "Upload files"}<FileInput className="sr-only" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" multiple onChange={upload} /></label></div><div className="mt-10 flex items-center justify-between"><div><h2 className="text-lg font-bold tracking-tight text-foreground">Uploaded files</h2><p className="mt-1 text-sm text-muted-foreground">{sources.length ? `${sources.length} files · ${reviewCount ? `${reviewCount} issue needs review` : "Everything understood"}` : "Your close files will appear here."}</p></div>{sources.length > 0 && <span className={cn("text-xs font-bold", reviewCount ? "text-warning" : "text-success")}>{reviewCount ? `${reviewCount} needs review` : "✓ All files understood"}</span>}</div><div className="mt-4 divide-y divide-border border-y border-border">{sources.map(source => <SourceRow key={source.id} source={source} onReview={() => setReviewSource(source)} />)}</div>{sources.length > 0 && <div className="mt-10 border-t border-border pt-7"><div className="flex items-center gap-2"><Check className="h-4 w-4 text-success" /><h2 className="text-sm font-bold text-foreground">{uncertain.length ? `${uncertain.length} data connection needs review` : `${sources.length} sources connected successfully`}</h2></div>{uncertain.map(item => <div key={item.id} className="mt-4 flex items-center justify-between gap-3 rounded-lg border border-warning/30 bg-warning/5 p-4"><div><div className="text-sm font-semibold text-foreground">Data connection needs review</div><p className="mt-1 text-xs text-muted-foreground">Duplicate references make this connection ambiguous.</p></div><Button asChild variant="outline" size="sm"><Link href={`/investigations/${investigationId}/relationships?relationship=${encodeURIComponent(item.id)}`}>Review connection</Link></Button></div>)}</div>}{reviewSource && <MappingReview source={reviewSource} investigationId={investigationId} onClose={() => setReviewSource(null)} onSaved={() => { setReviewSource(null); void refresh(); }} />}</div>; }
function SourceRow({ source, onReview }: { source: ApiSourceFile; onReview: () => void }) { const ready = source.status === "READY"; return <div className="flex items-center gap-4 py-4"><div className="flex h-9 w-9 shrink-0 items-center justify-center rounded-lg bg-muted text-muted-foreground">{source.original_filename.endsWith(".xlsx") ? <FileSpreadsheet className="h-4 w-4" /> : <FileText className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold text-foreground">{label(source.detected_source_type) || "Source"}</div><div className="mt-1 truncate text-xs text-muted-foreground">{source.original_filename} <span className="mx-1">·</span> {source.row_count.toLocaleString()} rows</div></div><div className={cn("hidden items-center gap-1.5 text-xs font-semibold sm:flex", ready ? "text-success" : "text-warning")}>{ready ? <Check className="h-3.5 w-3.5" /> : <CircleAlert className="h-3.5 w-3.5" />}{ready ? "Understood" : "1 issue needs review"}</div>{!ready && <Button variant="outline" size="sm" onClick={onReview}>Review</Button>}</div>; }
function MappingReview({ source, investigationId, onClose, onSaved }: { source: ApiSourceFile; investigationId: string; onClose: () => void; onSaved: () => void }) { const [analysis, setAnalysis] = React.useState<ApiSourceAnalysis | null>(null); const [mappings, setMappings] = React.useState<ApiSourceMapping[]>([]); const [selected, setSelected] = React.useState<ApiSourceMapping | null>(null); const [saving, setSaving] = React.useState(false); React.useEffect(() => { Promise.all([fetchSourceAnalysis(investigationId, source.id), fetchSourceMappings(investigationId, source.id)]).then(([a, m]) => { setAnalysis(a); setMappings(m); setSelected(m.find(item => item.required && !item.canonical_field) ?? m[0] ?? null); }).catch(() => undefined); }, [investigationId, source.id]); async function save() { if (!selected) return; setSaving(true); try { await editSourceMapping(investigationId, source.id, selected.id, { canonical_field: selected.canonical_field, ignored: selected.ignored }); await confirmSourceMappings(investigationId, source.id); onSaved(); } finally { setSaving(false); } } return <div className="fixed inset-0 z-30 flex items-end justify-center bg-foreground/20 p-4 sm:items-center"><div role="dialog" aria-modal="true" aria-labelledby="mapping-title" className="w-full max-w-lg rounded-2xl border border-border bg-card p-6 shadow-xl"><div className="flex items-start justify-between gap-4"><div><div className="text-[10px] font-bold uppercase tracking-[0.16em] text-muted-foreground">Needs review</div><h2 id="mapping-title" className="mt-2 text-lg font-bold text-foreground">{analysis ? `We are not sure what “${selected?.source_column ?? source.original_filename}” represents.` : "Checking this file…"}</h2></div><Button variant="ghost" size="icon" onClick={onClose} aria-label="Close"><X className="h-4 w-4" /></Button></div>{analysis && selected && <><div className="mt-6 rounded-lg bg-muted p-4"><div className="text-xs font-semibold text-foreground">Suggested: {label(selected.canonical_field) || "Order reference"}</div><div className="mt-2 text-xs text-muted-foreground">Confidence: {Math.round(selected.confidence * 100)}%</div></div><label className="mt-5 block text-xs font-semibold text-foreground">Choose another field<Select className="mt-2 h-10 w-full rounded-lg border border-input bg-card px-3 text-sm" value={selected.canonical_field ?? ""} onChange={e => setSelected({ ...selected, canonical_field: e.target.value })}><option value="">Select a field</option>{[...new Set(mappings.map(item => item.canonical_field).filter(Boolean) as string[])].map(field => <option key={field} value={field}>{label(field)}</option>)}</Select></label><div className="mt-6 flex justify-end gap-2"><Button variant="outline" onClick={onClose}>Cancel</Button><Button onClick={() => void save()} disabled={saving}>{saving ? "Saving…" : "Use suggestion"}</Button></div></>}</div></div>; }

export function CloseReconciliationPage({ investigationId }: { investigationId: string }) { return <CloseResultsPage investigationId={investigationId} />; }
export function CloseOverviewPage({ investigationId }: { investigationId: string }) { return <CloseHomeSummaryRoute investigationId={investigationId} />; }
function CloseHomeSummaryRoute({ investigationId }: { investigationId: string }) { const [investigation, setInvestigation] = React.useState<ApiFinancialInvestigation | null>(null); React.useEffect(() => { fetchFinancialInvestigation(investigationId).then(setInvestigation).catch(() => undefined); }, [investigationId]); return investigation ? <div className="mx-auto max-w-5xl"><CloseNav id={investigationId} /><HomeSummary investigation={investigation} /></div> : <div role="status" className="text-sm text-muted-foreground">Loading close…</div>; }
export function CloseResultsPage({ investigationId }: { investigationId: string }) { const [investigation, setInvestigation] = React.useState<ApiFinancialInvestigation | null>(null); const [run, setRun] = React.useState<ApiReconciliationRun | null>(null); const [results, setResults] = React.useState<ApiReconciliationResult[]>([]); const [error, setError] = React.useState<string | null>(null); const [query, setQuery] = React.useState(""); const params = useSearchParams(); React.useEffect(() => { fetchFinancialInvestigation(investigationId).then(setInvestigation).catch(e => setError(errorText(e))); fetchLatestReconciliation(investigationId).then(r => { setRun(r); return fetchReconciliationResults(investigationId, r.id); }).then(setResults).catch(() => undefined); }, [investigationId]); if (!investigation) return error ? <Alert variant="destructive"><AlertDescription>{error}</AlertDescription></Alert> : <div role="status" className="text-sm text-muted-foreground">Loading close results…</div>; const selected = results.find(item => item.id === params.get("result")); if (selected && run) return <CaseDetail investigation={investigation} run={run} result={selected} onBack={() => { window.location.href = `/investigations/${investigationId}/reconciliation`; }} />; const variance = results.filter(item => item.status === "RECONCILED_WITH_VARIANCE").length; const reconciled = run ? Math.max(0, run.reconciled_count - variance) : results.filter(item => item.status === "RECONCILED").length; const explained = run?.exception_count ?? results.filter(item => !inAttention(item) && item.status !== "RECONCILED" && item.status !== "RECONCILED_WITH_VARIANCE").length; const needsEvidenceCount = run?.ambiguous_count ?? results.filter(ambiguous).length; const filtered = results.filter(item => `${item.order_id} ${item.exception_type ?? ""} ${item.findings.map(finding => finding.code).join(" ")}`.toLowerCase().includes(query.toLowerCase())); return <div className="mx-auto max-w-5xl"><CloseNav id={investigationId} /><Heading eyebrow="Close results" title={investigation.name} description="A financial story you can act on: what reconciled, what FinTrace explained, and what still needs evidence or approval." />{run && <><div className="flex flex-wrap items-center gap-3"><span className="rounded-full bg-warning/10 px-3 py-1.5 text-xs font-bold text-warning">{results.some(inAttention) ? "Needs attention" : "Ready to sign off"}</span><span className="text-sm font-semibold text-foreground">{run.records_consumed.toLocaleString()} / {run.records_expected.toLocaleString()} records accounted for</span></div><div className="mt-7 grid grid-cols-2 gap-6 border-y border-border py-6 sm:grid-cols-4"><Metric name="Reconciled" value={String(reconciled)} color="text-success" /><Metric name="Expected variance" value={String(variance)} color="text-warning" /><Metric name="Explained" value={String(explained)} color="text-info" /><Metric name="Needs evidence" value={String(needsEvidenceCount)} color="text-destructive" /></div><div className="mt-6 flex flex-wrap gap-x-8 gap-y-2 text-sm text-muted-foreground"><span><strong className="font-bold text-foreground">{run.rejected_record_count}</strong> rejected</span><span><strong className="font-bold text-foreground">{run.orphan_record_count}</strong> orphaned</span><span>Potential exposure <strong className="font-bold text-foreground">{money(run.open_exposure_minor, investigation.base_currency)}</strong></span></div></>}<section className="mt-10"><div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between"><div><h2 className="text-lg font-bold tracking-tight text-foreground">What FinTrace found</h2><p className="mt-1 text-sm text-muted-foreground">Open a finding to see the evidence and lifecycle behind it.</p></div><div className="relative sm:w-72"><Search className="pointer-events-none absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" /><Input aria-label="Search results" className="pl-9" placeholder="Search order, payment, finding…" value={query} onChange={e => setQuery(e.target.value)} /></div></div><div className="mt-4 divide-y divide-border border-y border-border">{filtered.filter(item => item.status !== "RECONCILED").map(item => <ResultRow key={item.id} id={investigationId} result={item} currency={investigation.base_currency} />)}</div>{!filtered.filter(item => item.status !== "RECONCILED").length && <div className="py-10 text-sm text-muted-foreground">No findings match your search.</div>}</section></div>; }
function ResultRow({ id, result, currency }: { id: string; result: ApiReconciliationResult; currency: string }) { const current = state(result); return <Link href={`/investigations/${id}/reconciliation?result=${encodeURIComponent(result.id)}`} className="flex items-center gap-4 py-5 transition-colors hover:bg-muted/30"><div className={cn("flex h-8 w-8 shrink-0 items-center justify-center rounded-full", tone(current))}>{current === "NEEDS DECISION" ? <Info className="h-4 w-4" /> : <CircleAlert className="h-4 w-4" />}</div><div className="min-w-0 flex-1"><div className="text-sm font-bold text-foreground">{result.order_id}</div><div className="mt-1 text-xs text-muted-foreground">{label(result.exception_type ?? result.findings[0]?.code ?? "Finding")}</div></div><div className="hidden text-right sm:block"><div className={cn("text-[10px] font-bold uppercase tracking-wide", tone(current).split(" ")[0])}>{current}</div><div className="mt-1 text-sm font-semibold text-foreground">{money(result.exposure_minor, currency)}</div></div><ArrowRight className="h-4 w-4 shrink-0 text-muted-foreground" /></Link>; }

export function CloseAttentionPage({ investigationId }: { investigationId: string }) { const [investigation, setInvestigation] = React.useState<ApiFinancialInvestigation | null>(null); const [results, setResults] = React.useState<ApiReconciliationResult[]>([]); const [query, setQuery] = React.useState(""); const [filter, setFilter] = React.useState("ALL"); React.useEffect(() => { fetchFinancialInvestigation(investigationId).then(setInvestigation).catch(() => undefined); fetchLatestReconciliation(investigationId).then(run => fetchReconciliationResults(investigationId, run.id)).then(setResults).catch(() => undefined); }, [investigationId]); if (!investigation) return <div role="status" className="text-sm text-muted-foreground">Loading attention…</div>; const filtered = results.filter(inAttention).filter(item => `${item.order_id} ${label(item.exception_type)}`.toLowerCase().includes(query.toLowerCase())).filter(item => filter === "ALL" || state(item) === filter); return <div className="mx-auto max-w-5xl"><CloseNav id={investigationId} /><Heading eyebrow="Attention" title="Human work queue" description="Only needs evidence, needs decision, and approval-required items belong here. Explained findings stay out." /><div className="flex flex-col gap-3 border-b border-border pb-5 sm:flex-row"><div className="relative flex-1"><Search className="pointer-events-none absolute left-3 top-2.5 h-4 w-4 text-muted-foreground" /><Input aria-label="Search attention" className="pl-9" placeholder="Search order, payment, settlement…" value={query} onChange={e => setQuery(e.target.value)} /></div><div className="flex gap-2 overflow-x-auto"><FilterButton active={filter === "ALL"} onClick={() => setFilter("ALL")}>All</FilterButton><FilterButton active={filter === "NEEDS DECISION"} onClick={() => setFilter("NEEDS DECISION")}>Needs decision</FilterButton><FilterButton active={filter === "NEEDS EVIDENCE"} onClick={() => setFilter("NEEDS EVIDENCE")}>Needs evidence</FilterButton></div></div><div className="mt-5 text-sm font-semibold text-foreground">{filtered.length} item{filtered.length === 1 ? "" : "s"} need your attention</div><div className="mt-3 divide-y divide-border border-y border-border">{filtered.map(item => <ResultRow key={item.id} id={investigationId} result={item} currency={investigation.base_currency} />)}</div>{!filtered.length && <div className="py-10 text-sm text-muted-foreground">Nothing in the human work queue matches your search.</div>}</div>; }
function FilterButton({ active, onClick, children }: { active: boolean; onClick: () => void; children: React.ReactNode }) { return <Button type="button" onClick={onClick} className={cn("rounded-full border px-3 py-2 text-[11px] font-semibold", active ? "border-primary bg-primary text-primary-foreground" : "border-border text-muted-foreground hover:text-foreground")}>{children}</Button>; }

function CaseDetail({ investigation, run, result, onBack }: { investigation: ApiFinancialInvestigation; run: ApiReconciliationRun; result: ApiReconciliationResult; onBack: () => void }) { const [lifecycle, setLifecycle] = React.useState<ApiLifecycleResponse | null>(null); const [ai, setAi] = React.useState<ApiInvestigation | null>(null); const [investigating, setInvestigating] = React.useState(false); const [resolution, setResolution] = React.useState(false); const [error, setError] = React.useState<string | null>(null); React.useEffect(() => { fetchLifecycle(result.order_id).then(setLifecycle).catch(() => undefined); fetchReconciliationInvestigation(investigation.id, run.id, result.id).then(setAi).catch(() => undefined); }, [investigation.id, result.id, result.order_id, run.id]); const isAmbiguous = ambiguous(result); const isMissingSettlement = `${result.exception_type ?? ""} ${result.findings.map(item => item.code).join(" ")}`.includes("MISSING_SETTLEMENT"); const title = isAmbiguous ? "Ambiguous payment association" : isMissingSettlement ? "Missing settlement" : label(result.exception_type ?? "Finding"); const current = state(result); const isExplained = current === "EXPLAINED"; const order = lifecycle?.order ?? {}; const payments = lifecycle?.payments ?? []; const settlements = lifecycle?.settlements ?? []; async function investigate() { setInvestigating(true); setError(null); try { setAi(await investigateReconciliationResult(investigation.id, run.id, result.id)); } catch (e) { setError(errorText(e)); } finally { setInvestigating(false); } } async function requestDecision() { setResolution(true); try { await requestFinancialResolution(investigation.id, run.id, result.id, (isAmbiguous ? "REQUEST_PAYMENT_REVIEW" : "REQUEST_SETTLEMENT_REVIEW") as ResolutionActionCode); } catch (e) { setError(errorText(e)); } } return <div className="mx-auto max-w-6xl"><Button type="button" onClick={onBack} className="mb-6 flex items-center gap-2 text-xs font-semibold text-muted-foreground hover:text-foreground"><ArrowLeft className="h-3.5 w-3.5" />Back to results</Button><div className="mb-8 flex flex-col gap-4 border-b border-border pb-7 sm:flex-row sm:items-end sm:justify-between"><div><div className="mb-2 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground">{result.order_id} <span className="mx-1">·</span> Case detail</div><h1 className="text-[30px] font-bold tracking-[-0.04em] text-foreground">{title}</h1><p className="mt-3 max-w-2xl text-sm leading-6 text-muted-foreground">{isAmbiguous ? "Two payments match the same order and available evidence does not uniquely identify the correct one." : isMissingSettlement ? "Payment was captured successfully, but no matching settlement record was found." : "FinTrace found a break in the expected financial lifecycle."}</p></div><span className={cn("self-start rounded-full px-3 py-1.5 text-[11px] font-bold uppercase tracking-wide", tone(current))}>{current}</span></div>{error && <Alert variant="destructive" className="mb-5"><AlertDescription>{error}</AlertDescription></Alert>}<div className="grid gap-8 xl:grid-cols-[1fr_380px]"><div className="space-y-8"><section><div className="mb-4 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground">What happened</div><div className="max-w-2xl text-base leading-7 text-foreground">{isAmbiguous ? "Two candidate payments satisfy the available evidence. No unique reference safely identifies the correct payment." : isMissingSettlement ? "The payment was captured, but the expected settlement record is absent from the close dataset." : result.findings[0]?.message ?? "A lifecycle step does not match the expected close."}</div></section><section><div className="mb-4 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground">Financial lifecycle</div><div className="rounded-xl border border-border bg-card p-5"><LifecycleNode name="Order" id={String(order.order_id ?? result.order_id)} amount={Number(order.amount_minor ?? result.exposure_minor)} state="PRESENT" currency={investigation.base_currency} />{isAmbiguous && payments.length > 1 ? <div className="mt-5 grid gap-3 sm:grid-cols-2"><LifecycleNode name="Payment A" id={String(payments[0].payment_id ?? "PAYMENT A")} amount={Number(payments[0].amount_minor ?? 0)} state="AMBIGUOUS" currency={investigation.base_currency} detail={String(payments[0].captured_at ?? "").slice(11, 16)} /><LifecycleNode name="Payment B" id={String(payments[1].payment_id ?? "PAYMENT B")} amount={Number(payments[1].amount_minor ?? 0)} state="AMBIGUOUS" currency={investigation.base_currency} detail={String(payments[1].captured_at ?? "").slice(11, 16)} /></div> : <div className="mt-5"><LifecycleNode name="Payment" id={String(payments[0]?.payment_id ?? "Payment")} amount={Number(payments[0]?.amount_minor ?? result.exposure_minor)} state="PRESENT" currency={investigation.base_currency} /><div className="my-3 border-l border-dashed border-border pl-4 text-xs text-muted-foreground">↓ expected settlement</div><LifecycleNode name="Settlement" id={String(settlements[0]?.settlement_id ?? "Settlement")} amount={settlements.length ? Number(settlements[0].gross_amount_minor ?? settlements[0].gross_minor ?? 0) : undefined} state={settlements.length ? "PRESENT" : "EXPECTED BUT MISSING"} currency={investigation.base_currency} /></div>}{isAmbiguous && <div className="mt-5 border-t border-border pt-4 text-sm font-semibold text-destructive">? No unique reference available.</div>}</div></section><section><div className="mb-4 text-[10px] font-bold uppercase tracking-[0.18em] text-muted-foreground">{isExplained ? "How FinTrace established this" : "FinTrace investigation"}</div><div className="rounded-xl border border-primary/20 bg-primary/[0.025] p-6"><div className="flex items-start justify-between gap-4"><div><h2 className="text-lg font-bold text-foreground">{isExplained ? "Verified evidence" : "FinTrace Investigation"}</h2><p className="mt-1 text-sm leading-6 text-muted-foreground">{isExplained ? "The evidence trail that supports this explanation." : "FinTrace retrieves only the evidence needed to explain this case."}</p></div><ShieldCheck className="h-5 w-5 text-primary" /></div>{isExplained ? <ExplainedEvidence ai={ai} missingSettlement={isMissingSettlement} /> : !ai ? <><div className="mt-6 space-y-3"><InvestigationStep number="1" title="Checked order" detail={`${result.order_id} · ${money(result.exposure_minor, investigation.base_currency)}`} /><InvestigationStep number="2" title={isAmbiguous ? "Checked candidate payments" : "Checked expected settlement"} detail={isAmbiguous ? `${payments.length || 2} possible matches found` : "No matching record found"} /><InvestigationStep number="3" title="Checked supporting linkage" detail={isAmbiguous ? "No unique reference found" : "Expected record is missing"} /></div><div className="mt-6 flex items-center justify-between gap-3 border-t border-border pt-5"><div className="text-xs text-muted-foreground">Deterministic evidence is already available.</div><Button onClick={() => void investigate()} disabled={investigating}>{investigating ? "Checking evidence…" : "Investigate evidence"}</Button></div></> : <><InvestigationResult ai={ai} ambiguous={isAmbiguous} currency={investigation.base_currency} />{(ai.status === "FAILED" || ai.tool_calls.length === 0) && <Button className="mt-5" onClick={() => void investigate()} disabled={investigating}>{investigating ? "Checking source evidence…" : ai.status === "FAILED" ? "Retry AI investigation" : "Refresh investigation with source evidence"}</Button>}</>}</div></section></div><aside className="space-y-5"><div className="rounded-xl border border-warning/30 bg-warning/5 p-5"><div className="text-[10px] font-bold uppercase tracking-[0.16em] text-warning">Next step</div><h2 className="mt-2 text-base font-bold text-foreground">{isAmbiguous ? "Request a unique transaction reference" : isExplained ? "Send the settlement gap to payment operations" : "Review evidence"}</h2><p className="mt-2 text-sm leading-6 text-muted-foreground">No financial action is taken automatically.</p>{(isAmbiguous || isMissingSettlement) && <Button className="mt-5 w-full" onClick={() => void requestDecision()} disabled={resolution}>{resolution ? (isExplained ? "Follow-up sent" : "Reference requested") : isAmbiguous ? "Request transaction reference" : "Send to payment operations"}</Button>}</div><details className="rounded-xl border border-border bg-card"><summary className="flex cursor-pointer list-none items-center justify-between p-5 text-sm font-semibold text-foreground"><span>Technical details</span><ChevronDown className="h-4 w-4 text-muted-foreground" /></summary><div className="space-y-3 border-t border-border p-5 text-xs text-muted-foreground"><div className="flex justify-between gap-3"><span>Provider</span><span className="font-mono text-foreground">{ai?.provider ?? "—"}</span></div><div className="flex justify-between gap-3"><span>Model</span><span className="font-mono text-right text-foreground">{ai?.model ?? "—"}</span></div><div className="flex justify-between gap-3"><span>Tool calls</span><span className="font-mono text-foreground">{ai?.tool_calls.length ?? "—"}</span></div><div className="flex justify-between gap-3"><span>Verifier</span><span className="font-mono text-foreground">{ai ? (ai.verifier_passed ? "Passed" : "Issues") : "—"}</span></div></div></details></aside></div></div>; }
function ExplainedEvidence({ ai, missingSettlement }: { ai: ApiInvestigation | null; missingSettlement: boolean }) { return <div className="mt-6 space-y-4">{ai?.status === "SUPPORTED" ? <InvestigationResult ai={ai} ambiguous={false} /> : <div className="rounded-lg border border-success/20 bg-success/5 p-4 text-sm leading-6 text-foreground">The deterministic close evidence is sufficient to explain this finding. No further investigation is required.</div>}<div className="text-xs text-muted-foreground"><span className="font-bold text-foreground">Suggested next step:</span> {missingSettlement ? "Confirm settlement posting with payment operations." : "Acknowledge this explanation and continue the close."}</div></div>; }
function LifecycleNode({ name, id, amount, state: current, currency, detail }: { name: string; id: string; amount?: number; state: string; currency: string; detail?: string }) { return <div className={cn("rounded-lg border p-4", current === "EXPECTED BUT MISSING" ? "border-destructive/30 bg-destructive/5" : current === "AMBIGUOUS" ? "border-warning/40 bg-warning/5" : "border-border bg-background")}><div className="flex items-center justify-between gap-3"><span className="text-[10px] font-bold uppercase tracking-[0.14em] text-muted-foreground">{name}</span><span className={cn("text-[10px] font-bold", current === "PRESENT" ? "text-success" : current === "AMBIGUOUS" ? "text-warning" : "text-destructive")}>{current}</span></div><div className="mt-2 font-mono text-xs font-semibold text-foreground">{id}</div>{amount !== undefined && <div className="mt-2 text-lg font-bold text-foreground">{money(amount, currency)}</div>}{detail && <div className="mt-1 text-xs text-muted-foreground">{detail}</div>}</div>; }
function InvestigationStep({ number, title, detail }: { number: string; title: string; detail: string }) { return <div className="flex gap-3"><span className="flex h-6 w-6 shrink-0 items-center justify-center rounded-full bg-primary text-[11px] font-bold text-primary-foreground">{number}</span><div><div className="text-sm font-semibold text-foreground">{title}</div><div className="mt-1 text-xs text-muted-foreground">{detail}</div></div></div>; }
type InvestigationCitation = ApiInvestigation["supporting_evidence"][number];

function evidenceValue(item: InvestigationCitation, currency?: string) {
  if (item.operator === "missing") return "Not found in uploaded records";
  const value = item.expected_value;
  if (value === null || value === undefined) return item.fact;
  if (item.field?.endsWith("_minor") && typeof value === "number") {
    return currency ? money(value, currency) : `${value.toLocaleString()} minor units`;
  }
  if (item.field?.endsWith("_at") && typeof value === "string") {
    const parsed = new Date(value);
    if (!Number.isNaN(parsed.getTime())) return new Intl.DateTimeFormat("en-GB", {
      day: "numeric", month: "short", year: "numeric", hour: "2-digit", minute: "2-digit",
      second: "2-digit", timeZone: "UTC", timeZoneName: "short",
    }).format(parsed);
  }
  return String(value);
}

function InvestigationResult({ ai, ambiguous: isAmbiguous, currency }: { ai: ApiInvestigation; ambiguous: boolean; currency?: string }) {
  const supported = ai.status === "SUPPORTED" && !isAmbiguous;
  const failed = ai.status === "FAILED";
  const citations = [...ai.supporting_evidence, ...ai.contradictory_evidence];
  const groups = Array.from(citations.reduce((map, item) => {
    const key = `${item.source}:${item.record_id ?? "missing"}`;
    const group = map.get(key) ?? { source: item.source, id: item.record_id, items: [] as InvestigationCitation[] };
    if (!group.items.some(previous => previous.field === item.field && previous.operator === item.operator && previous.expected_value === item.expected_value)) group.items.push(item);
    map.set(key, group);
    return map;
  }, new Map<string, { source: string; id?: string | null; items: InvestigationCitation[] }>()).values());
  const payments = groups.filter(group => group.source === "payment" && group.id);
  const score = Math.max(0, Math.min(100, ai.evidence_score));
  const scoreLabel = score >= 90 ? "Strong evidence" : score >= 75 ? "Good evidence" : score >= 50 ? "Partial evidence" : "Limited evidence";
  const fieldLabels: Record<string, string> = {
    amount_minor: "Amount", gross_minor: "Gross amount", net_minor: "Net amount",
    fees_minor: "Fees", tax_minor: "Tax", captured_at: "Captured", created_at: "Created",
    settled_at: "Settled", processed_at: "Processed", order_id: "Order",
    payment_id: "Payment", gateway_reference: "Gateway reference", status: "Status",
    unit_cost_minor: "Unit cost", inventory_value_minor: "Inventory value",
  };
  const fieldName = (item: InvestigationCitation) => fieldLabels[item.field ?? ""] ?? label(item.field ?? "Evidence");
  return <>
    <div className="mt-6 grid gap-4 sm:grid-cols-[1fr_180px]">
      <div className={cn("rounded-xl border p-5", supported ? "border-success/20 bg-success/5" : failed ? "border-destructive/20 bg-destructive/5" : "border-warning/25 bg-warning/5")}>
        <div className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Investigation outcome</div>
        <h3 className="mt-2 text-lg font-bold tracking-tight text-foreground">{failed ? "Investigation unavailable" : supported ? "Supported explanation" : "Assessment · needs evidence"}</h3>
        <p className="mt-2 text-sm leading-6 text-foreground">{isAmbiguous && payments.length > 1 && !failed
          ? `${payments.length} payment records are associated with this order. The evidence does not yet establish whether these represent separate charges, a retry, or a linking error.`
          : ai.summary}</p>
        {isAmbiguous && payments.length > 1 && !failed && <p className="mt-3 text-xs leading-5 text-muted-foreground">A linked settlement shows which payment appears in the settlement export. It does not, by itself, explain the other payment.</p>}
      </div>
      <div className="rounded-xl border border-border bg-card p-5">
        <div className="text-xs font-semibold text-muted-foreground">Evidence confidence</div>
        <div className="mt-3 text-3xl font-bold tabular-nums tracking-tight text-foreground">{failed ? "—" : score}<span className="ml-1 text-sm font-normal text-muted-foreground">{failed ? "" : "/ 100"}</span></div>
        <p className="mt-2 text-xs font-semibold text-foreground">{failed ? "Assessment incomplete" : scoreLabel}</p>
        <p className="mt-3 text-[11px] leading-5 text-muted-foreground">Evidence score calculated by FinTrace. This is not the probability that an AI explanation is correct.</p>
      </div>
    </div>
    {payments.length > 1 && <section className="mt-6">
      <h3 className="text-sm font-semibold text-foreground">Compare the payments</h3>
      <div className="mt-3 grid gap-3 sm:grid-cols-2">{payments.map((payment, index) => {
        const links = citations.filter(item => item.verified && item.source === "settlement" && item.field === "payment_id" && item.operator === "equals" && item.expected_value === payment.id);
        return <div key={payment.id} className="min-w-0 rounded-xl border border-border bg-card p-4">
          <div className="text-xs font-semibold text-muted-foreground">Payment {index + 1}</div>
          <div className="mt-1 break-all font-mono text-xs font-semibold text-foreground">{payment.id}</div>
          <dl className="mt-4 space-y-3">{payment.items.filter(item => ["amount_minor", "captured_at", "gateway_reference", "status"].includes(item.field ?? "")).map((item, index) => <div key={index}><dt className="text-[11px] text-muted-foreground">{fieldName(item)}</dt><dd className="mt-1 break-words text-xs font-medium text-foreground">{evidenceValue(item, currency)}</dd></div>)}</dl>
          <div className="mt-4 border-t border-border pt-3 text-xs leading-5 text-muted-foreground">{links.length ? <>Settlement linked: <span className="break-all font-medium text-foreground">{Array.from(new Set(links.map(item => item.record_id))).join(", ")}</span></> : "No settlement link cited for this payment."}</div>
        </div>;
      })}</div>
    </section>}
    {ai.missing_evidence.length > 0 && <section className="mt-6 rounded-xl border border-border bg-card p-5">
      <h3 className="text-sm font-semibold text-foreground">What would resolve this</h3>
      {isAmbiguous && <p className="mt-2 text-sm leading-6 text-muted-foreground">Ask payment operations to check the gateway records for both payments and confirm whether the customer was charged once or twice.</p>}
      <ul className="mt-3 list-disc space-y-2 pl-4 text-xs leading-6 text-muted-foreground">{ai.missing_evidence.map((item, index) => <li className="break-words" key={index}>{item}</li>)}</ul>
    </section>}
    {isAmbiguous && payments.length > 1 && <details className="mt-5 rounded-lg border border-border bg-card p-4"><summary className="cursor-pointer text-xs font-semibold text-foreground">Full AI assessment</summary><p className="mt-3 whitespace-pre-line text-sm leading-6 text-muted-foreground">{ai.summary}</p></details>}
    {citations.length > 0 && <details className="mt-4 rounded-lg border border-border bg-card p-4">
      <summary className="cursor-pointer text-xs font-semibold text-foreground">Evidence cited in this assessment · {groups.length} records</summary>
      <div className="mt-4 divide-y divide-border">{groups.map((group, index) => <div key={index} className="py-4">
        <div className="break-all text-xs font-semibold text-foreground">{label(group.source)} · {group.id ?? "Absence in uploaded records"}</div>
        <dl className="mt-3 space-y-2">{group.items.map((item, index) => <div key={index} className="grid gap-1 text-xs sm:grid-cols-[120px_1fr]"><dt className="text-muted-foreground">{fieldName(item)}</dt><dd className="break-words text-foreground">{evidenceValue(item, currency)}{!item.verified && <span className="ml-2 text-warning">Unverified</span>}</dd></div>)}</dl>
      </div>)}</div>
    </details>}
    <p className="mt-4 text-xs leading-5 text-muted-foreground">{failed ? "AI assessment did not complete. The close evidence remains available." : ai.verifier_passed && citations.length > 0 ? `Cited fields passed verification.${supported ? "" : " The cause remains unresolved."}` : "Evidence verification is incomplete; review is required."}</p>
    <div className="mt-4 text-[11px] text-muted-foreground">{ai.provider === "stub" ? "Automated test fixture · not live AI" : `AI assessment · ${ai.provider} · ${ai.model}`}</div>
    {ai.tool_calls.length > 0 && <details className="mt-4 border-t border-border pt-4"><summary className="cursor-pointer text-xs font-semibold text-muted-foreground">Evidence lookups · {ai.tool_calls.length}</summary><div className="mt-4 space-y-3">{ai.tool_calls.map((tool, index) => <InvestigationStep key={`${tool.name}-${index}`} number={String(index + 1)} title={tool.name.replaceAll("_", " ")} detail={tool.result_summary} />)}</div></details>}
  </>;
}
